public ValidatedInt rollingChanceDenominator = new ValidatedInt(1800, 5000, 100);
@NonSync
@ConfigGroup.Pop
@Translatable.Name(value="Cartoon Rolling Sound")
@Translatable.Desc(value="If true, the hamster's rolling SFX will include a cartoon-ish slide whistle. It's subtle, but some people might get distracted easily or prefer more realism so I turned it off by default.")
