@Translatable.Name(value="Crop & Item Snacking")
@Translatable.Desc(value="Sometimes a hamster gets the munchies while wandering. If enabled, they will occasionally pillage your fully grown crops, accidentally replant seeds, and stuff the profits into their face. To see a list of crops and items hamsters may snack on, see the 'Core Item Tag Overrides' settings.")
public ConfigGroup cropSnacking = new ConfigGroup("cropSnacking", true);
@Translatable.Name(value="Snacking Chance")
@Translatable.Desc(value="How likely a wandering hamster is to attempt to steal crops. (1-in-X chance per tick). Default is 300 which equates to every 15 seconds on average. Set lower to increase the likelihood.")
public ValidatedInt cropSnackingChanceDenominator = new ValidatedInt(300, 10000, 1);
@Translatable.Name(value="Messiness")
@Translatable.Desc(value="The probability (0.0 to 1.0) that a hamster will accidentally replant a seed while aggressively harvesting a crop. At 0.0, they will perfectly uproot the crop, not spilling any seeds. At 1.0, they will be extremely messy and replant every time. Defaults to 0.75 (75%).")
public ValidatedFloat cropReplantChance = new ValidatedFloat(0.75f, 1.0f, 0.0f);
@Translatable.Name(value="Ignore Seeds")
@Translatable.Desc(value="If true, your hamster will ignore the seeds that drop during a midnight snack.")
public boolean ignoreSeeds = false;
@ConfigGroup.Pop
@Translatable.Name(value="Restrict to Wander Mode")
@Translatable.Desc(value="If true, hamsters will only scavenge for dropped snack items if they are actively in Wander Mode. If false, they might snatch up your dropped snackables while following you around.")
public boolean restrictItemSnackingToWanderMode = true;
@Translatable.Name(value="Independent Diamond Seeking")
@Translatable.Desc(value="Unleash free-range prospectors. What could go wrong?")
public ConfigGroup independentDiamondSeeking = new ConfigGroup("independentDiamondSeeking", true);
@Translatable.Name(value="Diamond Seek Scan Radius")
@Translatable.Desc(value="How far (in blocks) a hamster scans once it’s decided to play prospector.")
public ValidatedInt diamondSeekRadius = new ValidatedInt(10, 20, 5);
@Translatable.Name(value="Gold 'Mistake' Chance")
@Translatable.Desc(value="The probability (0.0 to 1.0) that a hamster will seek gold instead of diamond, if both are available. At 0.5, it's a coin toss. At 1.0, it's guaranteed hamster sulking.")
public ValidatedFloat goldMistakeChance = new ValidatedFloat(0.33f, 1.0f, 0.0f);
@Translatable.Name(value="Desirable Ores")
@Translatable.Desc(value="The list of blocks that smell... shiny. Especially to greedy hamsters. Diamonds by default, but maybe you want them to sniff for Zinc ore? Accepts block IDs (e.g. 'create:zinc_ore') and #tags (e.g. '#c:ores/diamond').")
public List<String> celebrationOres = new ArrayList<String>(List.of("minecraft:diamond_ore", "minecraft:deepslate_diamond_ore"));
@ConfigGroup.Pop
@Translatable.Name(value="Disappointing Ores")
@Translatable.Desc(value="Blocks that look promising but ultimately lead to a dramatic emotional breakdown. Gold by default, but if you want them to sniff for dirt, I'm not your conscience. Accepts block IDs (e.g. 'create:copper_ore') and #tags (e.g. '#c:ores/gold').")
public List<String> sulkingOres = new ArrayList<String>(List.of("minecraft:gold_ore", "minecraft:deepslate_gold_ore"));
@Translatable.Name(value="Item Stealing")
@Translatable.Desc(value="For when your hamster develops a taste for the finer things in life. Can be configured so they steal or fetch any item— even from other mods. They steal diamonds and fetch acorns by default.")
public ConfigGroup itemStealing = new ConfigGroup("itemStealing", true);
@ConfigGroup.Pop
@Translatable.Name(value="Thievery Pounce Chance")
@Translatable.Desc(value="Probability (0.1 to 1.0) a hamster will succumb to temptation when seeing a stealable item. High by default, since the only default stealable item is a diamond.")
public ValidatedFloat itemThieveryChance = new ValidatedFloat(0.75f, 1.0f, 0.1f);
@Translatable.Name(value="Tag Game")
@Translatable.Desc(value="Hamsters get bored. Sometimes they want to play. Configure the rules of engagement here.")
public ConfigGroup tagGame = new ConfigGroup("tagGame", true);
@Translatable.Name(value="Allow Stranger Danger")
@Translatable.Desc(value="If true, hamsters can ask any player to play. If false, they can only ask their owners.")
public boolean allowStrangerTag = true;
@Translatable.Name(value="Game Initiation Chance")
@Translatable.Desc(value="The 1-in-X chance per tick a hamster will start a game of tag with you if you make too much eye contact. Since the game runs at 20 ticks per second, a 1-in-500-tick chance means you'll need to maintain eye contact for about ~15 seconds on average. Set to 1 if you want the game to start instantly upon eye contact.")
public ValidatedInt tagChanceDenominator = new ValidatedInt(500, 1200, 1);
@Translatable.Name(value="Enable Player Daily Limit")
@Translatable.Desc(value="If true, players are capped on how many games they can play per day. If false, you can play until your legs fall off.")
public ValidatedBoolean enableTagGamePlayerLimit = new ValidatedBoolean(true);
private final ValidatedField<Boolean> isTagLimitEnabled = this.enableTagGamePlayerLimit.map(b -> b, b -> b);
