@Translatable.Desc(value="How many times a single player can be 'It' per Minecraft day before telling the rodents to go find a hobby. Prevents infinite reward farming.")
public ValidatedCondition<Integer> maxDailyTagGamesPerPlayer = new ValidatedInt(3, 100, 0).toCondition(this.isTagLimitEnabled, (Component)Component.m_237115_((String)"config.adorablehamsterpets.condition.tag_limit_enabled"), () -> 3);
